/* ============================================================
   Projectile range: R = v0^2 sin(2theta)/g   (two stacked panels)
   ============================================================ */
var FW = 660, FH = 790;
var fig = SVG().addTo(document.getElementById('container')).size('100%', '100%');
fig.viewbox(0, 0, FW, FH);
fig.rect(FW, FH).fill('#ffffff');

var C_OR = '#e8712e', C_PU = '#8e3f9c', C_TE = '#1f9e93';
var C_AX = '#8a8a8a', C_DASH = '#a8adb3', C_DIM = '#1a1a1a', C_TXT = '#111111';
var SERIF = '"Times New Roman", Georgia, serif';
var GRAV = 9.8;

/* world (metres) -> viewbox units */
var X0 = 100, SX = 548 / 285, SY = 1.5, GA = 245, GB = 655, XMAX = 650;
function mx(m) { return X0 + m * SX; }
function myA(h) { return GA - h * SY; }
function myB(h) { return GB - h * SY; }

function rangeOf(v, th) { return v * v * Math.sin(2 * th * Math.PI / 180) / GRAV; }
function apexOf(v, th) { var s = Math.sin(th * Math.PI / 180); return v * v * s * s / (2 * GRAV); }
function tofOf(v, th) { return 2 * v * Math.sin(th * Math.PI / 180) / GRAV; }

function trajPts(v, th, gy) {
  var R = rangeOf(v, th), n = 90, pts = [], rad = th * Math.PI / 180;
  var c = Math.cos(rad);
  for (var i = 0; i <= n; i++) {
    var xm = R * i / n;
    var h = xm * Math.tan(rad) - GRAV * xm * xm / (2 * v * v * c * c);
    if (h < 0) h = 0;
    var px = mx(xm);
    if (px > XMAX) break;
    pts.push([px, gy - h * SY]);
  }
  return pts;
}
function ptsStr(p) {
  var s = [];
  for (var i = 0; i < p.length; i++) s.push(p[i][0].toFixed(2) + ',' + p[i][1].toFixed(2));
  return s.join(' ');
}

function arrowTo(grp, x1, y1, x2, y2, color, w, dash) {
  var a = Math.atan2(y2 - y1, x2 - x1);
  var hl = 6 + 2.2 * w, hw = 2.0 + 1.1 * w;
  var bx = x2 - hl * Math.cos(a), by = y2 - hl * Math.sin(a);
  var ln = grp.line(x1, y1, bx, by).stroke({ color: color, width: w, linecap: 'round' });
  if (dash) ln.attr('stroke-dasharray', dash);
  grp.polygon([
    [x2, y2],
    [bx + hw * Math.sin(a), by - hw * Math.cos(a)],
    [bx - hw * Math.sin(a), by + hw * Math.cos(a)]
  ]).fill(color);
  return ln;
}

function txtLabel(grp, x, y, str, color, size, anchor, italic, halo) {
  var t = grp.plain(str).font({
    family: SERIF, size: size || 13, anchor: anchor || 'middle',
    style: italic ? 'italic' : 'normal'
  }).fill(color || C_TXT).attr({ x: x, y: y });
  if (halo !== false) {
    t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  }
  return t;
}

function dimBar(grp, x1, x2, y, label, color, size) {
  var c = color || C_DIM;
  grp.line(x1, y - 8, x1, y + 8).stroke({ color: c, width: 1.3 });
  grp.line(x2, y - 8, x2, y + 8).stroke({ color: c, width: 1.3 });
  var mid = (x1 + x2) / 2;
  arrowTo(grp, mid, y, x1, y, c, 1.3);
  arrowTo(grp, mid, y, x2, y, c, 1.3);
  return txtLabel(grp, mid, y + 4.5, label, c, size || 13.5, 'middle', true);
}

function arcPath(grp, cx, cy, r, a0, a1, color, w) {
  var x0 = cx + r * Math.cos(a0 * Math.PI / 180), y0 = cy - r * Math.sin(a0 * Math.PI / 180);
  var x1 = cx + r * Math.cos(a1 * Math.PI / 180), y1 = cy - r * Math.sin(a1 * Math.PI / 180);
  return grp.path('M' + x0.toFixed(2) + ' ' + y0.toFixed(2) + ' A' + r + ' ' + r + ' 0 0 0 ' +
    x1.toFixed(2) + ' ' + y1.toFixed(2)).fill('none').stroke({ color: color || '#333', width: w || 1 });
}

function hoverable(el, tip, ttl, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { showPopup(ttl, body); });
}

/* ---------- groups (z-order) ---------- */
var gStatic = fig.group();
var gA = fig.group();
var gB = fig.group();
var gTop = fig.group();

var refPathsA = [], refPathsB = [];

/* ============================================================
   STATIC LAYER
   ============================================================ */
function buildStatic() {
  /* ---------------- Panel (a) ---------------- */
  gStatic.line(92, GA, 648, GA).stroke({ color: C_AX, width: 1.6 });

  var refA = [{ v: 30, c: C_OR }, { v: 40, c: C_PU }, { v: 50, c: C_TE }];
  refA.forEach(function (d) {
    var R = rangeOf(d.v, 45), Hm = apexOf(d.v, 45), T = tofOf(d.v, 45);
    gStatic.line(mx(R / 2), myA(Hm), mx(R / 2), GA)
      .stroke({ color: C_DASH, width: 1, dasharray: '4,4' });
    var str = ptsStr(trajPts(d.v, 45, GA));
    var pl = gStatic.polyline(str).fill('none')
      .stroke({ color: d.c, width: 2, linecap: 'round', linejoin: 'round' }).opacity(0.78);
    refPathsA.push(pl);
    var hit = gStatic.polyline(str).fill('none')
      .stroke({ color: '#000', width: 14, opacity: 0 }).attr('pointer-events', 'stroke');
    hoverable(hit, d.v + ' m/s at 45°  →  R = ' + R.toFixed(1) + ' m',
      'Launched at ' + d.v + ' m/s, 45°',
      'R = v₀²·sin(2θ)/g = ' + d.v + '²·sin(90°)/9.8 = ' + R.toFixed(1) + ' m. Apex height H = ' +
      Hm.toFixed(1) + ' m and time of flight t = ' + T.toFixed(2) + ' s. Every one of these three curves leaves at the same 45°; only the speed differs.');
    var L = d.v * 2.4, tipx = X0 + L * 0.70711, tipy = GA - L * 0.70711;
    arrowTo(gStatic, X0, GA, tipx, tipy, d.c, 2);
    txtLabel(gTop, tipx - 9, tipy - 4, d.v + ' m/s', C_TXT, 13.5, 'end');
  });

  arcPath(gStatic, X0, GA, 46, 0, 45, '#444', 1);
  txtLabel(gTop, 164, 233, '45°', C_TXT, 13.5, 'middle');

  dimBar(gStatic, X0, mx(91.8), 300, 'R = 91.8 m', C_DIM);
  dimBar(gStatic, X0, mx(163), 330, 'R = 163 m', C_DIM);
  dimBar(gStatic, X0, mx(255), 360, 'R = 255 m', C_DIM);

  /* axis key, top right */
  arrowTo(gStatic, 596, 66, 596, 24, '#111', 1.4);
  arrowTo(gStatic, 596, 66, 642, 66, '#111', 1.4);
  txtLabel(gTop, 596, 18, 'y', '#111', 14, 'middle', true);
  txtLabel(gTop, 648, 70, 'x', '#111', 14, 'start', true);

  txtLabel(gTop, 370, 390, '(a)', C_TXT, 14, 'middle');

  /* ---------------- Panel (b) ---------------- */
  gStatic.line(92, GB, 648, GB).stroke({ color: C_AX, width: 1.6 });

  var Rsh = rangeOf(50, 15), H75 = apexOf(50, 75);
  gStatic.line(mx(Rsh), GB, mx(Rsh), myB(H75)).stroke({ color: C_DASH, width: 1, dasharray: '4,4' });
  gStatic.line(mx(Rsh / 2), GB, mx(Rsh / 2), myB(H75)).stroke({ color: C_DASH, width: 1, dasharray: '4,4' });

  var refB = [{ a: 15, c: C_OR }, { a: 45, c: C_PU }, { a: 75, c: C_TE }];
  refB.forEach(function (d) {
    var R = rangeOf(50, d.a), Hm = apexOf(50, d.a), T = tofOf(50, d.a);
    var str = ptsStr(trajPts(50, d.a, GB));
    var pl = gStatic.polyline(str).fill('none')
      .stroke({ color: d.c, width: 2, linecap: 'round', linejoin: 'round' }).opacity(0.78);
    refPathsB.push(pl);
    var hit = gStatic.polyline(str).fill('none')
      .stroke({ color: '#000', width: 14, opacity: 0 }).attr('pointer-events', 'stroke');
    hoverable(hit, '50 m/s at ' + d.a + '°  →  R = ' + R.toFixed(1) + ' m',
      '50 m/s launched at ' + d.a + '°',
      'sin(2·' + d.a + '°) = ' + Math.sin(2 * d.a * Math.PI / 180).toFixed(3) + ', so R = ' + R.toFixed(1) +
      ' m, H = ' + Hm.toFixed(1) + ' m, t = ' + T.toFixed(2) + ' s. Notice 15° and 75° give the same sin(2θ) and therefore the same range.');
    var L = 115, rad = d.a * Math.PI / 180;
    arrowTo(gStatic, X0, GB, X0 + L * Math.cos(rad), GB - L * Math.sin(rad), d.c, 2);
  });

  arcPath(gStatic, X0, GB, 62, 0, 15, '#444', 1);
  arcPath(gStatic, X0, GB, 78, 0, 45, '#444', 1);
  arcPath(gStatic, X0, GB, 94, 0, 75, '#444', 1);
  txtLabel(gTop, X0 + 48 * Math.cos(7.5 * Math.PI / 180), GB - 48 * Math.sin(7.5 * Math.PI / 180) + 4, '15°', C_TXT, 13, 'middle');
  txtLabel(gTop, X0 + 62 * Math.cos(30 * Math.PI / 180), GB - 62 * Math.sin(30 * Math.PI / 180) + 4, '45°', C_TXT, 13, 'middle');
  txtLabel(gTop, X0 + 78 * Math.cos(60 * Math.PI / 180), GB - 78 * Math.sin(60 * Math.PI / 180) + 4, '75°', C_TXT, 13, 'middle');

  /* v0 = 50 m/s label (composite so the subscript always renders) */
  txtLabel(gTop, 28, 470, 'v', C_TXT, 15, 'start', true);
  txtLabel(gTop, 37, 474, '0', C_TXT, 10, 'start');
  txtLabel(gTop, 45, 470, '= 50 m/s', C_TXT, 14, 'start');

  var b1 = dimBar(gStatic, X0, mx(128), 710, 'R = 128 m', C_DIM);
  var b2 = dimBar(gStatic, X0, mx(255), 738, 'R = 255 m', C_DIM);
  hoverable(b1, 'Both 15° and 75° land here', 'Complementary angles',
    'sin(2·15°) = sin(30°) = 0.5 and sin(2·75°) = sin(150°) = 0.5. Identical sin(2θ) means identical range (128 m), even though the 75° path climbs far higher and stays airborne much longer.');
  hoverable(b2, '45° gives the maximum range for 50 m/s', 'Why 45° is best',
    'sin(2θ) reaches its maximum value of 1 when 2θ = 90°, i.e. θ = 45°. That gives R = v₀²/g = 50²/9.8 = 255 m — no other launch angle at 50 m/s can beat it.');

