}

/* ============================================================
   DYNAMIC LAYERS
   ============================================================ */
var stateA = 30, stateB = 45, stateComp = false;

function nearRef(v, list) {
  for (var i = 0; i < list.length; i++) if (Math.abs(v - list[i]) < 0.6) return true;
  return false;
}

function drawA() {
  gA.clear();
  var v = stateA, th = 45;
  var col = v < 35 ? C_OR : (v < 45 ? C_PU : C_TE);
  var R = rangeOf(v, th), Hm = apexOf(v, th), T = tofOf(v, th);
  var onRef = nearRef(v, [30, 40, 50]);
  var dim = onRef ? 0.78 : 0.34;
  for (var i = 0; i < refPathsA.length; i++) refPathsA[i].opacity(dim);

  gA.line(mx(R / 2), myA(Hm), mx(R / 2), GA)
    .stroke({ color: col, width: 1.1, dasharray: '4,4' }).opacity(0.9);
  var pl = gA.polyline(ptsStr(trajPts(v, th, GA))).fill('none')
    .stroke({ color: col, width: 3.2, linecap: 'round', linejoin: 'round' });
  hoverable(pl, v + ' m/s at 45°  →  R = ' + R.toFixed(1) + ' m', 'Active trajectory (panel a)',
    'With θ locked at 45°, R = v₀²/g. Going from 30 to ' + v + ' m/s multiplies the speed by ' +
    (v / 30).toFixed(2) + ' but multiplies the range by ' + (R / rangeOf(30, 45)).toFixed(2) +
    ' — the square of that factor.');

  var L = v * 2.4;
  arrowTo(gA, X0, GA, X0 + L * 0.70711, GA - L * 0.70711, col, 2.7);

  if (!onRef) {
    dimBar(gA, X0, Math.min(mx(R), 646), 272, 'R = ' + R.toFixed(1) + ' m', col, 13);
  }

  var rx = 392, ry = 56;
  txtLabel(gA, rx, ry, 'v₀ = ' + v + ' m/s    θ = 45°', col, 13, 'start');
  txtLabel(gA, rx, ry + 17, 'R = ' + R.toFixed(1) + ' m    H = ' + Hm.toFixed(1) + ' m', '#444', 13, 'start');
  txtLabel(gA, rx, ry + 34, 't = ' + T.toFixed(2) + ' s', '#444', 13, 'start');
  if (mx(R) > XMAX) txtLabel(gA, rx, ry + 51, '(curve runs past the panel edge)', '#888', 11.5, 'start');
}

function drawB() {
  gB.clear();
  var v = 50, th = stateB;
  var col = th < 30 ? C_OR : (th < 60 ? C_PU : C_TE);
  var R = rangeOf(v, th), Hm = apexOf(v, th), T = tofOf(v, th);
  var onRef = nearRef(th, [15, 45, 75]);
  var dim = (onRef && !stateComp) ? 0.78 : 0.34;
  for (var i = 0; i < refPathsB.length; i++) refPathsB[i].opacity(dim);

  gB.line(mx(R / 2), myB(Hm), mx(R / 2), GB).stroke({ color: col, width: 1.1, dasharray: '4,4' }).opacity(0.9);
  gB.line(mx(R), GB, mx(R), myB(Hm)).stroke({ color: '#8b8f94', width: 1.1, dasharray: '4,4' }).opacity(0.9);

  var pl = gB.polyline(ptsStr(trajPts(v, th, GB))).fill('none')
    .stroke({ color: col, width: 3.2, linecap: 'round', linejoin: 'round' });
  hoverable(pl, '50 m/s at ' + th + '°  →  R = ' + R.toFixed(1) + ' m', 'Active trajectory (panel b)',
    'At fixed speed the range follows sin(2θ). Here sin(2·' + th + '°) = ' +
    Math.sin(2 * th * Math.PI / 180).toFixed(3) + ', giving R = ' + R.toFixed(1) +
    ' m out of the 255 m maximum available at 45°.');

  var L = 115, rad = th * Math.PI / 180;
  arrowTo(gB, X0, GB, X0 + L * Math.cos(rad), GB - L * Math.sin(rad), col, 2.7);

  var extra = 0;
  if (stateComp) {
    var th2 = 90 - th;
    var col2 = th2 < 30 ? C_OR : (th2 < 60 ? C_PU : C_TE);
    var H2 = apexOf(v, th2), T2 = tofOf(v, th2);
    var pc = gB.polyline(ptsStr(trajPts(v, th2, GB))).fill('none')
      .stroke({ color: col2, width: 2.6, linecap: 'round', linejoin: 'round', dasharray: '7,5' });
    hoverable(pc, 'complement ' + th2 + '°  →  same R = ' + R.toFixed(1) + ' m', 'The complementary launch',
      'θ = ' + th + '° and 90° − θ = ' + th2 + '° give the same sin(2θ), so both land at ' + R.toFixed(1) +
      ' m. Their apex heights (' + Hm.toFixed(1) + ' m vs ' + H2.toFixed(1) + ' m) and flight times (' +
      T.toFixed(2) + ' s vs ' + T2.toFixed(2) + ' s) are very different.');
    gB.line(mx(R / 2), myB(H2), mx(R / 2), GB).stroke({ color: col2, width: 1, dasharray: '3,4' }).opacity(0.75);
    arrowTo(gB, X0, GB, X0 + L * Math.cos(th2 * Math.PI / 180), GB - L * Math.sin(th2 * Math.PI / 180), col2, 2, '6,4');
    extra = 1;
  }

  if (!onRef) dimBar(gB, X0, Math.min(mx(R), 646), 682, 'R = ' + R.toFixed(1) + ' m', col, 13);

  var rx = 416, ry = 470;
  txtLabel(gB, rx, ry, 'v₀ = 50 m/s    θ = ' + th + '°', col, 13, 'start');
  txtLabel(gB, rx, ry + 17, 'R = ' + R.toFixed(1) + ' m    H = ' + Hm.toFixed(1) + ' m', '#444', 13, 'start');
  txtLabel(gB, rx, ry + 34, 't = ' + T.toFixed(2) + ' s', '#444', 13, 'start');
  if (extra) {
    var th2b = 90 - stateB;
    txtLabel(gB, rx, ry + 51, 'complement ' + th2b + '°: same R, H = ' + apexOf(50, th2b).toFixed(1) + ' m',
      '#666', 11.5, 'start');
  }
}

