  { title: 'Speed 50 m/s — range scales as v₀²', narration: 'At 50 m/s the projectile reaches 255 m. Comparing to 30 m/s: the speed ratio is 5/3 while the range ratio is 25/9. Range is proportional to v₀².', state: { speedA: 50, angleB: 45, showComplement: false } },
  { title: 'Now fix the speed and swing the angle', narration: 'In panel (b) the speed is locked at 50 m/s. At 45° the range is the same 255 m as before — this is the maximum any 50 m/s launch can achieve.', state: { speedA: 50, angleB: 45, showComplement: false } },
