  var dim = (onRef && !stateComp) ? 0.78 : 0.34;
  for (var i = 0; i < refPathsB.length; i++) refPathsB[i].opacity(dim);

  gB.line(mx(R / 2), myB(Hm), mx(R / 2), GB).stroke({ color: col, width: 1.1, dasharray: '4,4' }).opacity(0.9);
  gB.line(mx(R), GB, mx(R), myB(Hm)).stroke({ color: '#8b8f94', width: 1.1, dasharray: '4,4' }).opacity(0.9);

  var pl = gB.polyline(ptsStr(trajPts(v, th, GB))).fill('none')
    .stroke({ color: col, width: 3.2, linecap: 'round', linejoin: 'round' });
  hoverable(pl, '50 m/s at ' + th + '°  →  R = ' + R.toFixed(1) + ' m', 'Active trajectory (panel b)',
    'At fixed speed the range follows sin(2θ). Here sin(2·' + th + '°) = ' +
    Math.sin(2 * th * Math.PI / 180).toFixed(3) + ', giving R = ' + R.toFixed(1) +
    ' m out of the 255 m maximum available at 45°.');

  var L = 115, rad = th * Math.PI / 180;
  arrowTo(gB, X0, GB, X0 + L * Math.cos(rad), GB - L * Math.sin(rad), col, 2.7);

  var extra = 0;
  if (stateComp) {
    var th2 = 90 - th;
    var col2 = th2 < 30 ? C_OR : (th2 < 60 ? C_PU : C_TE);
    var H2 = apexOf(v, th2), T2 = tofOf(v, th2);
    var pc = gB.polyline(ptsStr(trajPts(v, th2, GB))).fill('none')
      .stroke({ color: col2, width: 2.6, linecap: 'round', linejoin: 'round', dasharray: '7,5' });
    hoverable(pc, 'complement ' + th2 + '°  →  same R = ' + R.toFixed(1) + ' m', 'The complementary launch',
      'θ = ' + th + '° and 90° − θ = ' + th2 + '° give the same sin(2θ), so both land at ' + R.toFixed(1) +
      ' m. Their apex heights (' + Hm.toFixed(1) + ' m vs ' + H2.toFixed(1) + ' m) and flight times (' +
      T.toFixed(2) + ' s vs ' + T2.toFixed(2) + ' s) are very different.');
    gB.line(mx(R / 2), myB(H2), mx(R / 2), GB).stroke({ color: col2, width: 1, dasharray: '3,4' }).opacity(0.75);
    arrowTo(gB, X0, GB, X0 + L * Math.cos(th2 * Math.PI / 180), GB - L * Math.sin(th2 * Math.PI / 180), col2, 2, '6,4');
    extra = 1;
  }

  if (!onRef) dimBar(gB, X0, Math.min(mx(R), 646), 682, 'R = ' + R.toFixed(1) + ' m', col, 13);

  var rx = 416, ry = 470;
  txtLabel(gB, rx, ry, 'v₀ = 50 m/s    θ = ' + th + '°', col, 13, 'start');
  txtLabel(gB, rx, ry + 17, 'R = ' + R.toFixed(1) + ' m    H = ' + Hm.toFixed(1) + ' m', '#444', 13, 'start');
  txtLabel(gB, rx, ry + 34, 't = ' + T.toFixed(2) + ' s', '#444', 13, 'start');
  if (extra) {
    var th2b = 90 - stateB;
    txtLabel(gB, rx, ry + 51, 'complement ' + th2b + '°: same R, H = ' + apexOf(50, th2b).toFixed(1) + ' m',
      '#666', 11.5, 'start');
  }
}

/* ---------- interaction handlers ---------- */
function update_speedA(v) { stateA = v; drawA(); }
function update_angleB(a) { stateB = a; drawB(); }
function toggle_showComplement(on) { stateComp = !!on; drawB(); }

/* ---------- demo step player ---------- */
var STEPS = [
  { title: 'Reference case: 30 m/s at 45°', narration: 'Panel (a) starts with the orange textbook trajectory: 30 m/s launched at 45° travels 91.8 m. The dashed line marks the apex, and the bar below measures the range.', state: { speedA: 30, angleB: 45, showComplement: false } },
  { title: 'Raise the speed to 40 m/s', narration: 'Drag the speed slider up. Speed rose by a factor of 4/3, but range jumped from 91.8 m to 163 m — a factor of (4/3)², not 4/3.', state: { speedA: 40, angleB: 45, showComplement: false } },
  { title: 'Speed 50 m/s — range scales as v₀²', narration: 'At 50 m/s the projectile reaches 255 m. Comparing to 30 m/s: the speed ratio is 5/3 while the range ratio is 25/9. Range is proportional to v₀².', state: { speedA: 50, angleB: 45, showComplement: false } },
  { title: 'Now fix the speed and swing the angle', narration: 'In panel (b) the speed is locked at 50 m/s. At 45° the range is the same 255 m as before — this is the maximum any 50 m/s launch can achieve.', state: { speedA: 50, angleB: 45, showComplement: false } },
  { title: 'A shallow 15° launch', narration: 'Drop the angle to 15°. The path is flat and fast but lands at only 128 m — the projectile simply is not in the air long enough.', state: { speedA: 50, angleB: 15, showComplement: false } },
  { title: 'Complementary angles share a range', narration: 'Turn on the complement to draw 75° alongside 15°. The tall arc and the flat arc land on the very same dashed line at 128 m, even though their peak heights and flight times are wildly different.', state: { speedA: 50, angleB: 15, showComplement: true } },
  { title: 'Why 45° wins', narration: 'Sweep back toward 45° with the complement still shown: the two curves merge, because 45° is its own complement. That coincidence is exactly where sin(2θ) peaks and range is greatest.', state: { speedA: 50, angleB: 45, showComplement: true } }
];
var curStep = 0;

function setStep(i) {
  curStep = (i % STEPS.length + STEPS.length) % STEPS.length;
  var s = STEPS[curStep];
  var sa = document.getElementById('speedAInput');
  if (sa) { sa.value = s.state.speedA; document.getElementById('speedAVal').value = s.state.speedA; }
  update_speedA(+s.state.speedA);
  var ab = document.getElementById('angleBInput');
  if (ab) { ab.value = s.state.angleB; document.getElementById('angleBVal').value = s.state.angleB; }
  update_angleB(+s.state.angleB);
  var cb = document.getElementById('showComplementInput');
  if (cb) cb.checked = !!s.state.showComplement;
  toggle_showComplement(!!s.state.showComplement);
  var n = document.getElementById('demoNarration');
  if (n) n.innerHTML = '<b>' + s.title + '</b><br>' + s.narration;
  var lb = document.getElementById('stepLabel');
  if (lb) lb.textContent = (curStep + 1) + ' / ' + STEPS.length;
}
function nextStep() { setStep(curStep + 1); }
function prevStep() { setStep(curStep - 1); }

/* ---------- go ---------- */
buildStatic();
setStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
